  E("программное обеспечение", [7], { m: "mix", q: "Компьютер без программ — что он умеет? А можно ли бесплатно скопировать любую программу и раздать друзьям?", hyp: "без программ ничего; программы бывают разные; копировать нельзя без разрешения автора", goal: "Какие бывают программы и что можно делать с ними по закону?", f: ["Программы делят на системные (операционная система, драйверы, служебные), прикладные (текст, графика, таблицы, игры) и системы программирования.", "Программы и данные охраняются авторским правом: нельзя копировать и распространять без разрешения правообладателя.", "Бывают коммерческие, условно-бесплатные, бесплатные и свободные программы — у каждой своя лицензия."], t: ["системное ПО", "прикладное ПО", "лицензия", "авторское право", "свободное ПО"], a: "brow", l: "reestr,lo,cc", fl: ["cards_po", "cards_lic"], s: ["Откройте файл «karty_po.csv» и распределите программы по группам: системное, прикладное, служебное, система программирования.", "Откройте «karty_licenzii.csv» и подберите к описанию вид лицензии.", "Сверьте с соседом и обсудите спорные карточки.", "Найдите на компьютере три установленные программы и определите для каждой тип."], done: "Программы разнесены по группам, к каждому описанию подобран вид лицензии.", chk: ["Не путают «бесплатная» и «свободная» (свободная — можно изучать и изменять)."], hw: "Составьте таблицу из пяти программ, которыми пользуетесь: название, тип, платная или нет." });
  E("файлы и папки", [7], { m: "mix", q: "Что проще найти — один нужный документ среди тысячи в одной куче или в аккуратных папках? Как компьютер «помнит», где что лежит?", hyp: "в папках быстрее; у каждого файла есть имя и место", goal: "Как устроена файловая система и как записать путь к файлу?", f: ["Файл — именованная область памяти; папка (каталог) хранит файлы и другие папки, образуя дерево.", "Полное имя файла включает путь: диск, папки и имя с расширением, например «C:\\Школа\\7 класс\\доклад.docx».", "Расширение (после последней точки) показывает тип файла."], t: ["файл", "папка", "путь к файлу", "расширение", "файловая система"], a: "os", l: "csu", fl: ["tree"], s: ["Откройте папку «Сортировка» и посмотрите на файлы: по каким признакам их можно разделить на группы?", "Включите показ расширений: Проводник → Вид → «Расширения имён файлов» (Linux: значок «Показать скрытые файлы» не нужен, расширение видно сразу).", "Определите тип каждого файла по расширению (запишите в тетрадь: .txt, .bmp, .wav, .py, .html, .csv).", "Выберите любой файл и напишите его полный путь от диска."], done: "Файлы разделены на группы по типам; записан полный путь к файлу.", chk: ["Ученики понимают, что расширение не меняют вручную."], hw: "Нарисуйте схему папок на своём компьютере или телефоне и запишите полный путь к любимому файлу." });
  E("основные операции с файлами", [7, 10], { m: "pc", q: "Рабочий стол завален файлами «Новый документ (3).txt». Как навести порядок за пять минут и ничего не потерять?", hyp: "создать папки, разложить файлы по типам, переименовать, лишнее удалить", goal: "Какие операции с файлами и папками нужны, чтобы навести порядок?", f: ["Основные операции: создать, переименовать, копировать, переместить, удалить, найти.", "При копировании остаётся оригинал, при перемещении файл исчезает из старого места.", "Удалённый файл попадает в корзину и может быть восстановлен до её очистки."], t: ["копирование", "перемещение", "переименование", "корзина", "поиск файлов"], a: "os", l: "res", fl: ["tree"], s: ["Откройте папку «Сортировка». Прочитайте файл «читай_меня.txt».", "Внутри папки «Сортировка» создайте папки: «Документы», «Изображения», «Звуки», «Программы», «Данные».", "Переместите (перетащите) файлы в подходящие папки по расширению. Файл «страница.html» положите в «Программы».", "Найдите две копии одного доклада и удалите копию (файл с « — копия» в имени).", "Переименуйте «Новый текстовый документ.txt» в «план_урока.txt».", "Скопируйте папку «Изображения» на рабочий стол, а затем удалите копию.", "Используя поиск, найдите все файлы с расширением .txt (маска *.txt) и запишите, сколько их."], adv: ["Закрепите ярлык на папку «Данные» на рабочем столе.", "Сделайте так, чтобы файлы в папке отображались таблицей с датой и размером."], done: "Папка «Сортировка» разложена на 5 папок; лишние файлы удалены; найдены .txt файлы.", chk: ["Ученики не удаляют нужные файлы вместо копий.", "Проверяйте результат по дереву папок, а не по рабочему столу."], hw: "Дома разложите свои фотографии или документы по папкам (по датам или темам). Опишите правила, по которым разложили." });
  E("сравнение размеров", [7], { m: "pc", q: "Почему фотография «весит» как десять страниц текста, а песня — как сотня фотографий? Что определяет размер файла?", hyp: "число пикселей; качество звука; длительность; сжатие", goal: "От чего зависит размер текстового, графического и звукового файла?", f: ["Размер текста зависит от числа символов и кодировки; один символ в UTF-8 — 1 байт для латиницы и 2 байта для кириллицы.", "Размер несжатого растрового рисунка = число пикселей × глубина цвета (бит на пиксель) / 8.", "Размер звука = частота дискретизации × глубина × время × число каналов / 8."], t: ["байт", "килобайт", "мегабайт", "глубина цвета", "частота дискретизации"], a: "os,tab", l: "auda", fl: ["sizes"], s: ["Откройте папку «Размеры». В файле «tablica_razmerov.csv» (откройте в электронных таблицах) уже перечислены файлы.", "Для каждого файла откройте свойства (правая кнопка → «Свойства») и запишите размер в байтах.", "Подсчитайте в таблице размер в КиБ (делите на 1024) и во сколько раз файл больше текстового. Используйте формулу, а не калькулятор.", "Сравните рисунки 100×100 и 200×200: во сколько раз больше второй? Объясните.", "Сравните три звука: что изменилось в названии файла и как это связано с размером?", "Сделайте вывод: какие файлы самые «тяжёлые» и почему."], adv: ["Рассчитайте размер файла «рисунок_100x100.bmp» по формуле и сравните с реальным (почему есть разница в 54 байта?)."], done: "Заполнена таблица размеров; сделан вывод о причинах разницы.", chk: ["Размер и «размер на диске» — разные числа: на диске выделяются целые кластеры.", "КиБ = 1024 байт."], hw: "Найдите на телефоне фото, песню и короткое видео. Запишите их размеры и сравните." });
  E("архивация", [7], { m: "pc", q: "Как отправить по почте 50 фотографий, если ящик принимает вложения не больше 25 МБ? Всегда ли архив уменьшает файл?", hyp: "заархивировать; архив сжимает; не всегда — зависит от файла", goal: "Как работает архивация и что сжимается лучше всего?", f: ["Архивация — упаковка данных в файл-архив, обычно меньшего размера; обратный процесс — распаковка.", "Сжатие эффективно, когда в данных много повторов (текст, несжатые рисунки BMP), и почти не помогает для уже сжатых форматов (JPEG, MP3, ZIP) и случайных данных.", "Степень сжатия = размер архива / исходный размер (или доля сэкономленного)."], t: ["архив", "архиватор", "степень сжатия", "распаковка"], a: "arch,os,tab", l: "z7", fl: ["archive"], s: ["Откройте папку «Архив». В таблице «tablica_arhivacii.csv» запишите исходные размеры четырёх файлов.", "Создайте архив каждого файла отдельно: правая кнопка → «7-Zip → Добавить к «имя.zip»» (или «Отправить → Сжатая ZIP-папка»).", "Запишите размер каждого архива.", "Посчитайте степень сжатия: (1 − размер архива / исходный размер) × 100 %, формулой в электронной таблице.", "Объясните, какой файл сжался сильнее всех и какой почти не сжался.", "Распакуйте один архив в новую папку и убедитесь, что файл совпадает по размеру."], adv: ["Создайте архив из всех файлов сразу и сравните с суммой отдельных архивов.", "Установите пароль на архив (формат 7z/ZIP, шифрование AES) и проверьте открытие без пароля."], done: "Заполнена таблица сжатия; сделан вывод, какие данные сжимаются хорошо.", chk: ["Файл sluchaynye_dannye.dat почти не сжимается — это ожидаемо."], hw: "Заархивируйте папку с докладом и фото для одноклассника: сравните размеры." });
  E("защита информации от компьютерных вирусов|компьютерные вирусы", [7], { m: "mix", q: "Компьютер вдруг стал «тормозить», на рабочем столе появились незнакомые значки, а друг прислал ссылку «посмотри, там про тебя». Что могло произойти и что делать?", hyp: "вирус; нельзя нажимать ссылку; нужно проверить антивирусом; рассказать взрослым", goal: "Как вирусы попадают на компьютер и как защититься?", f: ["Компьютерный вирус — вредоносная программа, способная копировать себя и вредить данным; есть также трояны, шпионские и вымогательские программы.", "Основные пути заражения: вложения в письмах, ссылки, внешние накопители, программы из сомнительных источников.", "Защита: антивирус с обновляемыми базами, обновление системы, резервные копии, осторожность с ссылками и вложениями."], t: ["вредоносная программа", "антивирус", "резервная копия", "фишинг"], a: "av,os", l: "setev", fl: ["cards_po", "pass"], s: ["Найдите в системе антивирус и посмотрите: включён ли он, когда обновлялись базы (запишите дату).", "Запустите проверку выбранной папки «Сортировка» (правая кнопка → «Проверить на вирусы»).", "Откройте «proverka_parolya.html» и проверьте три придуманных (не настоящих!) пароля. Запишите, какие признаки делают пароль слабым.", "Составьте памятку «Пять правил безопасной работы»: ссылки, вложения, флешки, пароли, обновления.", "Обсудите в парах, что делать, если файл не открывается и компьютер ведёт себя странно."], done: "Выполнена проверка папки, составлена памятка из пяти правил.", chk: ["Не запускайте настоящие вирусы: тренируемся на безопасных данных.", "Пароли в тренажёр не вводят настоящие."], hw: "Расскажите дома о правилах безопасной работы; запишите, кто что из них уже делал." });
  E("компьютерные сети", [7], { m: "mix", q: "Вы отправили фото другу. Через какие устройства оно прошло, прежде чем появилось у него на экране?", hyp: "через роутер, провода или Wi-Fi, серверы, Интернет", goal: "Как устроена сеть и что такое Интернет?", f: ["Компьютерная сеть соединяет компьютеры для обмена данными; бывают локальные (в одном здании) и глобальные.", "Интернет — всемирная система связанных сетей; данные передаются пакетами по протоколам.", "У каждого узла есть адрес; для сайтов используются доменные имена, которые преобразуются в адреса."], t: ["локальная сеть", "Интернет", "сервер", "протокол", "IP-адрес"], a: "cmd,brow", l: "fil,csu", fl: [], s: ["Откройте командную строку (карточка учителя) и введите «ipconfig» (Linux: «ip a»). Найдите свой IP-адрес и запишите.", "Введите «ping 127.0.0.1» и объясните, что означает ответ (проверка собственного сетевого интерфейса).", "Спросите у учителя адрес школьного шлюза и введите «ping» с этим адресом: сколько миллисекунд отвечает?", "Откройте сайт школы в браузере и найдите в адресной строке доменное имя. Что в нём «страна», а что «название»?"], done: "Записаны IP-адрес, результат ping и разбор доменного имени.", chk: ["Используйте только безопасные команды; не запускайте сканеры портов."], hw: "Нарисуйте схему сети дома: какие устройства подключены к роутеру." });
  E("поиск информации по ключевым словам", [7], { m: "pc", q: "Вы ищете «где купить рюкзак» и получаете миллион страниц. Как задать запрос так, чтобы нужный сайт оказался в первой десятке?", hyp: "добавить слова; взять точную фразу; исключить лишнее; искать по картинке", goal: "Как формулировать поисковый запрос и искать информацию по изображению?", f: ["Поисковая система находит страницы по словам запроса; чем точнее слова, тем лучше результат.", "Операторы: кавычки — точная фраза; минус перед словом исключает слово; вертикальная черта — «или». Подробности — в справке поисковика.", "Поиск по изображению помогает найти источник картинки и похожие изображения."], t: ["ключевые слова", "поисковый запрос", "источник информации", "достоверность"], a: "brow", l: "yah", fl: [], s: ["Откройте поисковую систему и найдите: «столица Австралии». Запишите ответ и адрес сайта, на котором нашли.", "Найдите ту же информацию на втором сайте и сравните ответы.", "Составьте запрос с точной фразой в кавычках и запрос с исключением слова минусом. Сравните число результатов.", "Загрузите картинку (выданную учителем) в поиск по изображению и определите, что на ней и откуда она.", "Заполните таблицу: запрос — что получилось — что изменить."], done: "Найдены ответы на 3 вопроса с указанием источников; освоены оператор кавычек и минус.", chk: ["Требуйте указывать адрес сайта и дату обращения."], hw: "Найдите три факта о выбранной теме на двух разных сайтах и сравните." });
  E("интернет-коммуникации", [7], { m: "mix", q: "В чате незнакомый человек просит прислать фото и адрес «для конкурса». Что делать и почему?", hyp: "не отправлять; рассказать взрослым; заблокировать", goal: "Как безопасно общаться в Интернете?", f: ["Интернет-коммуникации: почта, мессенджеры, форумы, видеосвязь, соцсети.", "Личные данные (адрес, школа, телефон, пароли) нельзя сообщать незнакомым; нужно настраивать приватность.", "При угрозах и травле нужно сохранить доказательства и обратиться ко взрослым."], t: ["электронная почта", "мессенджер", "приватность", "кибербуллинг", "этикет сети"], a: "brow", l: "setev", fl: ["pass"], s: ["В учебной почте или учебном чате (выданном учителем) отправьте соседу сообщение с темой и вложением (файл из папки).", "Составьте письмо по правилам: тема, обращение, текст, подпись.", "Откройте «proverka_parolya.html», придумайте надёжный пароль-образец и объясните, чем он хорош.", "Разберите три ситуации из памятки (карточки учителя) и выберите правильные действия.", "Составьте «Правила общения в сети» из 5 пунктов."], done: "Отправлено учебное письмо; составлены правила безопасного общения.", chk: ["Используйте учебные аккаунты; личные не вводить.", "Настоящие пароли в тренажёр не вводить."], hw: "Проверьте настройки приватности в любимом сервисе (вместе с родителями) и запишите, что изменили." });
  E("^информация и информационные процессы", [7], { m: "unp", q: "Учитель читает вам вслух, вы пишете в тетрадь. Что здесь происходит с информацией на каждом этапе?", hyp: "передача, запись, хранение, обработка", goal: "Что такое информация и какие процессы с ней происходят?", f: ["Информация — сведения об окружающем мире, которые уменьшают неопределённость.", "Информационные процессы: сбор, хранение, передача и обработка.", "Информацию можно воспринимать разными органами чувств и хранить на разных носителях."], t: ["информация", "носитель информации", "информационный процесс"], l: "csu", fl: ["cards_process"], s: ["Откройте «karty_processy.csv» и определите процесс в каждой ситуации: сбор, хранение, передача или обработка.", "Обсудите спорные карточки в паре."], done: "Каждая ситуация отнесена к своему информационному процессу.", hw: "Опишите три информационных процесса, которые происходят дома за вечер." });
  E("хранение, передача и обработка", [7], { m: "unp", q: "Что общего между книгой, облаком, флешкой и пещерным рисунком — и что различается?", hyp: "всё хранит информацию; носитель и скорость разные", goal: "Как информация хранится, передаётся и обрабатывается?", f: ["Носители: бумага, магнитные, оптические, полупроводниковые (флеш-память), облачные хранилища.", "Передача: источник → канал → приёмник; помехи искажают сообщение.", "Обработка: получение новой информации из имеющейся — вычисление, сортировка, преобразование."], t: ["канал связи", "помехи", "облачное хранилище"], l: "csu", fl: ["cards_process"], s: ["Составьте таблицу «Носитель — как хранит — плюсы — минусы» для четырёх носителей.", "Придумайте пример передачи информации с помехами и объясните, как их уменьшить."], done: "Составлена таблица носителей, разобран пример передачи.", hw: "Опишите, как вы храните свои фотографии и что будет, если один носитель сломается." });
  E("представление информации", [7], { m: "unp", q: "Как записать информацию так, чтобы её поняли и человек, и компьютер: на бумаге рисунком, словами, цифрами — а в компьютере?", hyp: "нужен алфавит знаков; компьютеру подходит только 0 и 1", goal: "Что такое знаки, алфавит и как кодировать информацию?", f: ["Знак — условное обозначение; алфавит — набор знаков; мощность алфавита — их число N.", "Двоичный алфавит из двух знаков (0 и 1) используют компьютеры.", "Кодирование — запись информации с помощью знаков алфавита по правилам; декодирование — обратный процесс."], t: ["алфавит", "мощность алфавита", "кодирование", "двоичный код"], a: "brow", l: "csu", fl: ["binary"], s: ["Откройте «dvoichnye_kartochki.html». Включайте карточки и наблюдайте, как меняется число.", "Получите числа 5, 12, 37, 100.", "Решите тренажёр «переведи в двоичную» и дойдите до 5 верных ответов."], done: "Освоены двоичные карточки: получены числа и решено 5 примеров.", hw: "Запишите свой возраст и день рождения в двоичной системе." });
  E("кодирование текстовой", [7], { m: "pc", q: "Почему на одном компьютере текст читается нормально, а на другом превращается в «РџСЂРёРІРµС‚»?", hyp: "разные таблицы кодов (кодировки); компьютер читает не ту таблицу", goal: "Как кодируется текст и что такое кодировка?", f: ["Каждому символу соответствует числовой код; соответствие записано в кодовой таблице (кодировке).", "Распространены кодировки: ASCII (128 символов), Windows-1251 (1 байт на символ, включая кириллицу), Юникод (UTF-8, UTF-16).", "Если файл прочитать не в той кодировке, вместо текста получаются «кракозябры»."], t: ["кодировка", "код символа", "Юникод", "байт"], a: "note,txt,brow", l: "csu", fl: ["codes"], s: ["Откройте файл «tablica_kodov.html» в браузере и введите «Привет». Запишите коды символов в Юникоде и в Windows-1251.", "Откройте файлы из папки «kodirovki» в Блокноте (или текстовом редакторе): что видите? Попробуйте открыть в другой кодировке (Блокнот: Файл → Открыть, внизу «Кодировка»; Writer: окно «Импорт текста»).", "Для каждого файла запишите, в какой кодировке он читается правильно.", "Определите размер каждого файла в байтах и объясните разницу.", "Сохраните свой текст «Привет, школа!» в UTF-8 и в Windows-1251; сравните размеры."], done: "Определены кодировки трёх файлов; записаны коды символов; сравнены размеры.", chk: ["Не все версии Блокнота показывают одинаковые названия кодировок: ориентируйтесь на «UTF-8», «ANSI/Windows-1251», «Юникод (UTF-16)»."], hw: "Закодируйте своё имя кодами символов (Юникод) и дайте соседу расшифровать." });
  E("кодирование цвета", [7], { m: "pc", q: "Как экран «рисует» миллионы оттенков, если в нём только три цвета светящихся точек?", hyp: "смешивает красный, зелёный и синий в разных пропорциях", goal: "Как кодируется цвет в компьютере?", f: ["Цвет на экране получают смешением красного (R), зелёного (G) и синего (B).", "Яркость каждой составляющей — число от 0 до 255, то есть один байт; на пиксель приходится 24 бита.", "Цвет можно записать десятичными числами RGB(255, 128, 0) или шестнадцатеричным кодом #FF8000."], t: ["модель RGB", "палитра", "глубина цвета", "пиксель"], a: "rast,brow", l: "pph", fl: ["rgb"], s: ["Откройте «tsvet_rgb.html» и подберите бегунками красный, зелёный, синий, жёлтый, белый, чёрный. Запишите коды в «tsveta_zadanie.csv».", "Сыграйте в «Угадай цвет»: добейтесь расстояния менее 40 пять раз подряд.", "В Paint (или другом редакторе) откройте «Изменение цвета» и введите свои значения RGB: проверьте, что цвет совпал.", "Узнайте код любого цвета на картинке инструментом «Пипетка» и запишите его.", "Подсчитайте: сколько цветов можно получить при 24 битах (256³)."], done: "Заполнена таблица цветов; определены коды цветов на картинке.", chk: ["Сложение цветов на экране не равно смешению красок: свет, а не краска."], hw: "Подберите три цвета для школьной афиши и запишите их RGB-коды." });
  E("кодирование растровых", [7], { m: "pc", q: "Увеличим фото в несколько раз — почему оно рассыпается на квадратики? А рисунок в векторе — нет?", hyp: "растр состоит из пикселей; вектор — из формул", goal: "Как кодируются растровые изображения и как формат влияет на размер?", f: ["Растровое изображение — сетка пикселей; каждому пикселю соответствует код цвета.", "Размер несжатого рисунка = ширина × высота × глубина цвета / 8 байт.", "Форматы: BMP (без сжатия), PNG (сжатие без потерь), JPEG (с потерями), GIF (до 256 цветов)."], t: ["растр", "разрешение", "формат файла", "сжатие с потерями"], a: "rast,os", l: "gimp,krita", fl: ["raster"], s: ["Откройте «risunok_64x64.bmp» в графическом редакторе и увеличьте масштаб до 800 %: что видите?", "Сохраните рисунок как PNG, как JPEG (качество 50 %), как GIF. Назовите файлы по форматам.", "Откройте папку и запишите размеры всех четырёх файлов в таблицу.", "Объясните, какой формат лучше для чертежа, а какой для фотографии.", "Закодируйте чёрно-белую картинку 8×8 в «pixel_8x8_zadanie.csv»: впишите 0 и 1, затем запишите 8 байт (по строкам) в двоичной записи."], done: "Рисунок сохранён в 4 форматах, размеры сравнены, закодирована картинка 8×8.", chk: ["JPEG ухудшает качество; не сохраняйте в нём исходник."], hw: "Нарисуйте свой смайлик 8×8 в клетчатой тетради и закодируйте его нулями и единицами." });
  E("кодирование звука", [7], { m: "pc", q: "Звук — это волна, а в компьютере — числа. Как волну превратить в числа и не потерять мелодию?", hyp: "измерять высоту волны много раз в секунду; чем чаще и точнее, тем лучше", goal: "Как кодируется звук и от чего зависит качество?", f: ["Звук записывают дискретизацией: через равные промежутки времени измеряют уровень сигнала и округляют до целого числа.", "Частота дискретизации — число измерений в секунду (Гц); глубина кодирования — число бит на одно измерение.", "Чем выше частота и глубина, тем лучше качество и тем больше файл."], t: ["дискретизация", "частота дискретизации", "глубина кодирования", "моно/стерео"], a: "aud,brow", l: "auda", fl: ["sound"], s: ["Откройте «diskretizaciya_zvuka.html» и меняйте число измерений и глубину: что происходит с «ступенчатой» линией?", "Запишите в «tablica_zvuka.csv» расчётный размер для трёх вариантов.", "Запишите в Audacity (или «Запись голоса») фразу 5 секунд при частоте 8000 Гц, затем 44100 Гц (Audacity: левый нижний угол «Частота проекта»).", "Экспортируйте обе записи в WAV и сравните размеры файлов и качество на слух.", "Сверьте расчёт с реальным размером и объясните разницу."], done: "Сделаны две записи разного качества; расчёт совпал с размером файла.", chk: ["Если нет микрофонов, используйте готовый файл zvuk_ton_440.wav и меняйте частоту проекта в Audacity (Правка → Параметры или «Частота проекта»)."], hw: "Рассчитайте размер минуты звука CD-качества (44 100 Гц, 16 бит, стерео)." });
  E("кодирование видео", [7], { m: "mix", q: "Фильм длиной два часа занимает на диске в десятки раз больше памяти, чем книга. Откуда берётся такой объём?", hyp: "много кадров в секунду и звук; каждый кадр — картинка", goal: "Как кодируется видео и как измерять количество информации?", f: ["Видео — последовательность кадров (изображений) и звуковая дорожка; обычно 24–60 кадров в секунду.", "Единицы: 1 байт = 8 бит; 1 КиБ = 1024 байт; 1 МиБ = 1024 КиБ; 1 ГиБ = 1024 МиБ.", "Видео почти всегда сжимают (кодеки), иначе оно было бы огромным."], t: ["кадр", "частота кадров", "кодек", "килобайт", "мегабайт"], a: "tab,brow", l: "res", fl: ["sizes"], s: ["Рассчитайте в электронной таблице размер несжатого видео: ширина × высота × 3 байта × кадров в секунду × секунды, для 640×480, 25 кадров/с, 10 секунд.", "Переведите результат в МиБ и ГиБ формулами.", "Сравните с типичным размером сжатого короткого видео на телефоне (посмотрите свойства файла).", "Сделайте вывод о роли сжатия."], done: "Рассчитан размер несжатого видео, сделан вывод о сжатии.", hw: "Рассчитайте, сколько секунд видео 640×480 (несжатого) поместится на флешку 8 ГиБ." });
  E("решение задач на измерение", [7], { m: "mix", q: "Сколько страниц текста помещается на диске объёмом 1 ГиБ? Как это узнать без эксперимента?", hyp: "размер страницы делим на размер диска", goal: "Как решать задачи на измерение информации?", f: ["Информационный объём текста = число символов × информационный вес символа.", "Вес символа i бит связан с мощностью алфавита N: N = 2^i.", "Объём растрового рисунка и звука считают по формулам из прошлых уроков."], t: ["информационный объём", "вес символа"], a: "tab", fl: [], fam: "vol", s: ["Решите в электронной таблице три задачи уровня «базовый», записывая формулы.", "Сверьте с ответом на листе.", "Придумайте свою задачу и обменяйтесь ею с соседом."], hw: "Составьте и решите задачу про объём своей любимой песни." });
  E("обобщение по теме", [7], { m: "mix", q: "Что общего в кодировании текста, цвета и звука — и что может помочь, если вы забыли формулу?", hyp: "везде дискретизация и числа; формулы похожи", goal: "Как связаны разные виды кодирования?", f: ["Любая информация в компьютере — числа в двоичном коде.", "Объём = количество элементов × вес элемента.", "Качество и размер связаны: больше точность — больше файл."], a: "tab,brow", l: "csu", fl: ["codes", "rgb", "sound"], fam: "vol", s: ["Откройте любой из тренажёров (коды, цвета, звук) и ответьте на вопрос по своей карточке.", "Составьте общую схему «Что кодируем — как — единицы — формула объёма»."], done: "Составлена общая схема кодирования информации.", hw: "Подготовьтесь к контрольной: повторите единицы информации и формулы." });
  E("клавиатурное письмо|текстовые документы", [7], { m: "pc", q: "Одни пишут текст за минуту, другие — за десять. Дело только в скорости пальцев или в способе работы?", hyp: "в слепом методе, в знании сочетаний клавиш, в умении исправлять", goal: "Как быстро и правильно вводить и редактировать текст?", f: ["Клавиатурное письмо — ввод текста десятью пальцами без взгляда на клавиатуру.", "Редактирование: выделение, копирование, вставка, удаление, отмена действия.", "Сочетания клавиш: Ctrl+C, Ctrl+V, Ctrl+X, Ctrl+Z, Ctrl+A, Ctrl+S."], t: ["текстовый процессор", "курсор", "буфер обмена", "выделение"], a: "txt,brow", l: "klv", fl: ["docdraft"], s: ["Разомнитесь 5 минут на тренажёре (если выход в Интернет запрещён, перепечатайте абзацы из файла «chernovik.txt»). Запишите скорость.", "Откройте «chernovik.txt» в текстовом процессоре и сохраните как «Фамилия_документ.docx».", "Исправьте ошибки, которые вы найдёте при чтении; разделите текст на разделы.", "Используйте сочетания клавиш для копирования и перемещения абзацев; не используйте мышь для этих операций.", "Сохраните документ (Ctrl+S) и закройте программу."], adv: ["Напечатайте за 3 минуты текст из 100 слов без ошибок."], done: "Создан и сохранён документ; освоены горячие клавиши.", chk: ["Сидеть правильно: спина прямая, экран на уровне глаз, запястья расслаблены."], hw: "Потренируйтесь в клавиатурном письме 10 минут и запишите результат." });
  E("форматирование символов и абзацев", [7], { m: "pc", q: "Два документа с одним текстом: один читается легко, другой — раздражает. В чём разница?", hyp: "в оформлении: шрифты, интервалы, выравнивание", goal: "Как форматировать символы и абзацы?", f: ["Форматирование символов: шрифт, размер, начертание, цвет.", "Форматирование абзацев: выравнивание, отступ первой строки, междустрочный интервал.", "Единый стиль оформления облегчает чтение; для заголовков используют стили."], t: ["шрифт", "абзац", "отступ", "интервал", "стиль"], a: "txt", l: "lo", fl: ["docdraft"], s: ["Откройте «chernovik.txt» в текстовом процессоре.", "Заголовки «Раздел …» сделайте стилем «Заголовок 1» (Word: Главная → Стили; Writer: Формат → Стили).", "Основной текст: шрифт Times New Roman (или Liberation Serif) 14 pt, интервал 1,5, выравнивание по ширине, красная строка 1,25 см.", "Выделите ключевые слова полужирным начертанием, но не больше 5 мест.", "Сохраните как «Фамилия_формат.docx»."], adv: ["Создайте собственный стиль «Мой абзац» и примените ко всем абзацам."], done: "Документ оформлен по требованиям: единые шрифт, интервал, выравнивание, заголовки.", chk: ["Не форматируйте вручную каждый абзац — используйте стили."], hw: "Оформите реферат по любому предмету по требованиям, выданным учителем." });
  E("параметры страницы|колонтитул", [7], { m: "pc", q: "Как сделать документ похожим на настоящую брошюру: номера страниц, название сверху, правильные поля?", hyp: "параметры страницы; колонтитулы; нумерация", goal: "Как задать параметры страницы и добавить колонтитулы и номера?", f: ["Параметры страницы: размер бумаги, ориентация, поля.", "Колонтитулы — области в верхней и нижней частях страницы, повторяющиеся на всех страницах.", "Номера страниц вставляют автоматически."], t: ["поля", "ориентация страницы", "колонтитул", "нумерация страниц"], a: "txt", fl: ["docdraft"], s: ["Откройте «chernovik.txt» и сохраните как «Фамилия_страницы.docx».", "Задайте поля: левое 3 см, правое 1,5 см, верхнее и нижнее 2 см (Word: Макет → Поля; Writer: Формат → Страница).", "Вставьте верхний колонтитул с названием работы и нижний с номером страницы по центру.", "Сделайте титульную страницу без номера (разные колонтитулы для первой страницы).", "Проверьте через предварительный просмотр печати."], done: "Документ с заданными полями, колонтитулами и номерами страниц, титульный лист без номера.", hw: "Сделайте обложку для школьной тетради и оформите колонтитул." });
