  E("системы счисления\\. позиционные", [8], { m: "unp", q: "Римляне записывали числа буквами, мы — цифрами. Почему римское XVIII читать труднее, чем 18, и как «умеет» считать компьютер, у которого только 0 и 1?", hyp: "позиция цифры важна; в римской системе значение не зависит от места; компьютеру удобна система с двумя цифрами", goal: "Чем позиционные системы счисления отличаются от непозиционных?", f: ["В непозиционной системе значение цифры не зависит от её места (римская: X всегда 10).", "В позиционной значение цифры зависит от позиции: 345 = 3·10² + 4·10 + 5.", "Основание системы — число используемых цифр (десятичная — 10, двоичная — 2)."], t: ["система счисления", "позиционная система", "основание", "разряд"], a: "brow", l: "csu", fl: ["binary"], fam: "ns", s: ["Откройте «dvoichnye_kartochki.html» и составьте число 37, затем 100 из карточек.", "Заполните «chisla_zadanie.csv»: переведите числа в двоичную, восьмеричную, шестнадцатеричную системы (Калькулятор → режим «Программист»)."], hw: "Запишите в двоичной системе номер своей квартиры и год рождения." });
  E("двоичная система счисления", [8], { m: "unp", q: "Как записать число 37 только нулями и единицами, и как быстро восстановить число по записи 100101?", hyp: "делить на 2 и записывать остатки; складывать степени двойки", goal: "Как переводить целые числа между десятичной и двоичной системами?", f: ["Перевод в двоичную: делим число на 2, записываем остатки справа налево.", "Перевод из двоичной: складываем степени двойки там, где стоят единицы: 100101₂ = 32 + 4 + 1 = 37.", "Степени двойки полезно знать до 2¹⁰ = 1024."], t: ["двоичная система", "бит", "остаток"], a: "brow", l: "csu", fl: ["binary"], fam: "ns", s: ["Работайте с тренажёром: дойдите до 10 верных ответов.", "Составьте таблицу степеней двойки до 2¹⁰."], hw: "Переведите 5 чисел из списка в двоичную и обратно." });
  E("перевод чисел с помощью калькулятора", [8], { m: "pc", q: "Проверить перевод чисел вручную долго. Как использовать инструменты компьютера, чтобы быстро проверять себя, и не превратить это в «списывание»?", hyp: "калькулятор в режиме «Программист» показывает числа сразу в нескольких системах", goal: "Как использовать калькулятор для перевода чисел и проверки вычислений?", f: ["В режиме «Программист» калькулятор показывает число в HEX, DEC, OCT, BIN.", "Калькулятор — средство проверки: сначала считаем сами.", "Электронные таблицы тоже умеют: функции ДЕС.В.ДВ и ДВ.В.ДЕС (в LibreOffice DEC2BIN, BIN2DEC)."], t: ["калькулятор «Программист»", "HEX", "DEC", "OCT", "BIN"], a: "tab", fl: ["binary"], fam: "ns", s: ["Откройте Калькулятор и включите режим «Программист» (Windows: ≡ → Программист; Linux: Режим → Программирование).", "Для каждого числа из «chisla_zadanie.csv» сначала переведите вручную, потом проверьте калькулятором.", "Отметьте в таблице, где ошиблись, и найдите причину.", "В электронной таблице введите формулу =ДЕС.В.ДВ(37) (в LibreOffice: =DEC2BIN(37)) и убедитесь в совпадении.", "Сохраните таблицу как «Фамилия_СС.xlsx»."], adv: ["Выясните, какое наибольшее число поместится в 1 байт и в 2 байта."], done: "Заполнена таблица с переводами; найдены и исправлены ошибки.", hw: "Составьте 5 чисел и обменяйтесь с соседом для проверки." });
  E("восьмеричная и шестнадцатеричная", [8], { m: "unp", q: "Двоичная запись 1010111100 длинная и неудобная. Как записать то же число короче и не запутаться?", hyp: "объединять разряды группами", goal: "Как связаны двоичная, восьмеричная и шестнадцатеричная системы?", f: ["Одна восьмеричная цифра — три двоичных разряда, одна шестнадцатеричная — четыре.", "Цифры шестнадцатеричной системы: 0–9 и A–F (A=10, …, F=15).", "Перевод между двоичной и 8/16-ричной — заменой групп разрядов по таблице."], t: ["восьмеричная система", "шестнадцатеричная система", "тетрада", "триада"], a: "tab", fl: ["binary"], fam: "ns", s: ["Составьте таблицу тетрад: 0000–1111 и соответствующие HEX-цифры.", "Переведите 5 двоичных чисел в 16-ричную группами, затем проверьте калькулятором."], hw: "Запишите свой цвет RGB (из прошлого года) в двоичной и шестнадцатеричной системах." });
  E("арифметические операции в двоичной", [8], { m: "unp", q: "Компьютер складывает, умножая и вычитая только единицы и нули. Как он это делает?", hyp: "по правилам: 1 + 1 = 10 (с переносом)", goal: "Как выполнять арифметические операции в двоичной системе?", f: ["Таблица сложения: 0+0=0, 0+1=1, 1+1=10 (0 и перенос 1), 1+1+1=11.", "Сложение выполняют столбиком справа налево с переносом.", "Умножение на 2 — сдвиг влево; деление на 2 — сдвиг вправо."], t: ["перенос", "сдвиг"], a: "brow", fl: ["binary"], fam: "nsadd", s: ["Сложите столбиком 5 пар двоичных чисел и проверьте переводом в десятичную.", "Выполните умножение на 2 и 4 сдвигом."], hw: "Придумайте две пары чисел и выполните сложение в двоичной системе." });
  E("контрольная работа по теме .системы счисления", [8], { m: "unp", ctrl: true, fam: "ns", q: "Как проверить, что вы умеете переводить числа?", hyp: "", goal: "Проверка по теме «Системы счисления».", f: [] });
  E("понятие высказывания", [8], { m: "unp", q: "«Сегодня вторник» — это утверждение, а «Закрой дверь!» — нет. Чем отличаются, и как компьютер решает, правда или ложь?", hyp: "высказывание можно оценить как истинное или ложное", goal: "Что такое высказывание и какие есть логические операции?", f: ["Высказывание — предложение, о котором можно сказать, истинно оно или ложно.", "Основные операции: НЕ (инверсия), И (конъюнкция), ИЛИ (дизъюнкция).", "Составные высказывания собирают из простых с помощью связок; истинность зависит от истинности частей."], t: ["высказывание", "конъюнкция", "дизъюнкция", "инверсия"], a: "brow", fl: ["gates"], fam: "logic", s: ["Откройте «logicheskie_elementy.html» и переключайте A и B: запишите, какой результат у И, ИЛИ, НЕ.", "Приведите по примеру высказывания для каждой операции."], hw: "Составьте 5 высказываний из жизни и определите, истинны ли они." });
  E("^таблицы истинности$", [8], { m: "unp", q: "Как проверить логическое выражение при всех возможных значениях, не гадая?", hyp: "перебрать все сочетания 0 и 1 и записать результаты в таблицу", goal: "Как строить таблицу истинности?", f: ["Для n переменных в таблице 2ⁿ строк.", "Столбцы заполняют по порядку выполнения операций (сначала скобки, затем НЕ, затем И, затем ИЛИ).", "Выражения с одинаковыми таблицами равносильны."], t: ["таблица истинности", "равносильность"], a: "brow", fl: ["truth"], fam: "logic", s: ["Откройте «tablica_istinnosti.html» и введите выражение A and not B: сравните со своей таблицей.", "Постройте вручную таблицу для (A or B) and not C и сверьте."], hw: "Постройте таблицы истинности для 3 выражений." });
  E("таблицы истинности в электронной таблице", [8], { m: "pc", q: "Как построить таблицу истинности для 3 переменных быстро и не ошибаться — и можно ли доверить это компьютеру?", hyp: "в электронных таблицах есть функции И, ИЛИ, НЕ", goal: "Как построить таблицу истинности в электронной таблице?", f: ["В электронных таблицах логические функции: И(a;b), ИЛИ(a;b), НЕ(a). Значения ИСТИНА/ЛОЖЬ.", "Формулу пишут один раз и копируют вниз.", "Проверять результаты можно сравнением с ручным расчётом."], t: ["функция И", "функция ИЛИ", "функция НЕ", "ИСТИНА/ЛОЖЬ"], a: "tab", fl: ["truth"], fam: "logic", s: ["Откройте «vyrazheniya.csv» в электронных таблицах: в столбцах B, C, D — все сочетания значений A, B, C (0/1).", "В столбец A запишите формулу для выражения НЕ(A) И (B ИЛИ C), например =И(НЕ(B2=1);ИЛИ(C2=1;D2=1)) (подставьте адреса).", "Скопируйте формулу вниз на 8 строк и проверьте результат вручную.", "Для второго выражения (A ИЛИ B) И НЕ(C) повторите.", "Сохраните как «Фамилия_логика.xlsx»."], adv: ["Подсчитайте, в скольких строках выражение истинно (функция СЧЁТЕСЛИ)."], done: "Построены таблицы истинности для двух выражений.", hw: "Составьте три выражения и построите их таблицы." });
  E("логические выражения", [8], { m: "unp", q: "Можно ли заменить сложное условие в программе простым, чтобы оно работало так же?", hyp: "да, по законам логики", goal: "Какие законы логики помогают упрощать выражения?", f: ["Законы: двойное отрицание, коммутативность, ассоциативность, дистрибутивность, законы де Моргана.", "Де Морган: НЕ(A И B) = НЕ A ИЛИ НЕ B; НЕ(A ИЛИ B) = НЕ A И НЕ B.", "Равносильность проверяют таблицей истинности."], t: ["закон де Моргана", "тождество"], a: "brow", fl: ["truth"], fam: "logic", s: ["Проверьте закон де Моргана на странице «tablica_istinnosti.html»: сравните столбцы для not (A and B) и (not A) or (not B).", "Упростите три выражения и проверьте."], hw: "Упростите выражения из карточки." });
  E("логические элементы", [8], { m: "mix", q: "Из чего собрано «мышление» компьютера — как из переключателей получаются вычисления?", hyp: "из элементов, реализующих И, ИЛИ, НЕ", goal: "Как работают логические элементы и схемы?", f: ["Логический элемент реализует логическую операцию над сигналами 0/1.", "Из элементов И, ИЛИ, НЕ собирают схемы любой сложности.", "Сумматор — схема, складывающая двоичные числа."], t: ["логический элемент", "схема", "сумматор"], a: "brow", l: "fal", fl: ["gates"], fam: "logic", s: ["Откройте «logicheskie_elementy.html»: проверьте для каждого элемента таблицу.", "Нарисуйте на бумаге схему для выражения (A И B) ИЛИ НЕ C."], hw: "Нарисуйте схему для (A ИЛИ B) И НЕ A." });
  E("контрольная работа по теме .элементы математической логики", [8], { m: "unp", ctrl: true, fam: "logic", q: "Как проверить логические умения?", hyp: "", goal: "Проверка по теме «Элементы математической логики».", f: [] });
  E("понятие алгоритма", [8], { m: "unp", q: "Рецепт, инструкция к стиральной машине, маршрут — что общего и чем алгоритм отличается от обычного описания?", hyp: "чёткие шаги в нужном порядке", goal: "Что такое алгоритм и исполнитель, какими свойствами обладает алгоритм?", f: ["Алгоритм — конечная последовательность чётких команд для исполнителя.", "Свойства: дискретность, понятность, определённость, результативность, массовость.", "Исполнитель — тот, кто выполняет алгоритм; у него есть система команд и среда."], t: ["алгоритм", "исполнитель", "команда", "среда исполнителя"], a: "brow", l: "blk,lbot,hoc", fl: ["robot_1"], s: ["Откройте «robot_1.html» и посмотрите, как работает Робот: напишите линейный алгоритм по подсказке.", "Запишите свойства алгоритма на примере."], hw: "Запишите алгоритм заваривания чая для исполнителя, который ничего не знает." });
  E("исполнитель робот. линейные", [8], { m: "pc", q: "Роботу нельзя сказать «иди к двери» — он понимает только простые команды. Как написать для него точную программу?", hyp: "разбить путь на шаги и записать каждую команду", goal: "Как составить линейный алгоритм для исполнителя Робот?", f: ["Линейный алгоритм выполняется строго по порядку без повторов и условий.", "Алгоритм должен подходить к каждому исходному состоянию среды, для которого его задумали.", "Ошибки: пропущена команда, лишняя команда, неверное направление."], t: ["линейный алгоритм", "программа исполнителя"], a: "kumir,brow", l: "kum,blk", fl: ["robot_1", "robot_6"], s: ["Откройте «robot_1.html» в браузере (или аналогичное задание в КуМире: Робот).", "Выполните задачу «Дорожка»: закрасьте отмеченные клетки и остановитесь в «СТОП».", "Нажмите «Выполнить» и следите за роботом; исправляйте ошибки.", "Откройте «robot_6.html» (Лабиринт): проведите Робота по лабиринту линейной программой.", "Запишите число команд в вашем решении. Можно ли короче?"], adv: ["Решите «Лабиринт» меньшим числом команд."], done: "Решены две задачи: закрашена дорожка, пройден лабиринт.", chk: ["Не забудьте, что в КуМире Робот программируется на «алгоритмическом языке»: команды «вверх», «вниз», «влево», «вправо», «закрасить»."], hw: "Придумайте и запишите маршрут Робота в клетчатой тетради." });
  E("способы записи алгоритмов", [8], { m: "unp", q: "Один и тот же алгоритм можно записать словами, схемой или программой. Когда какая запись удобнее?", hyp: "словесная — для людей, блок-схема — для наглядности, программа — для машины", goal: "Какие есть способы записи алгоритмов?", f: ["Способы: словесный, построчный, блок-схема, программа на языке программирования.", "Блок-схема: овал — начало/конец, прямоугольник — действие, ромб — условие, параллелограмм — ввод/вывод.", "Все записи должны быть равносильны."], t: ["блок-схема", "псевдокод"], a: "gv", l: "dio", fl: [], s: ["Нарисуйте в draw.io блок-схему алгоритма «Чай» или «Переход дороги».", "Запишите тот же алгоритм словами."], hw: "Нарисуйте блок-схему алгоритма нахождения большего из двух чисел." });
  E("преобразование алгоритма из одной формы записи", [8], { m: "pc", q: "У вас есть блок-схема, а исполнителю нужна программа. Как не потерять смысл при переписывании?", hyp: "по блокам: действие — команда, ромб — условие", goal: "Как преобразовать алгоритм из одной формы записи в другую?", f: ["Каждому блоку блок-схемы соответствует команда или конструкция языка.", "Проверка: прогон по одинаковым исходным данным.", "Ветвление и цикл имеют типовые формы записи в разных способах."], t: ["блок-схема", "программа", "преобразование"], a: "gv,kumir", l: "dio", fl: ["robot_2"], s: ["Откройте «robot_2.html» (Лесенка) и решите задачу сначала линейно (по одной команде), затем с повтором.", "Нарисуйте блок-схему вашего решения с циклом в draw.io.", "Запишите алгоритм словесно (3–4 строки).", "Проверьте, что три записи дают одинаковый результат."], done: "Алгоритм «Лесенка» записан тремя способами.", hw: "Запишите алгоритм «Рамка» тремя способами." });
  E("алгоритмическая конструкция .повторение", [8], { m: "unp", q: "Нужно написать 100 раз «Я не опаздываю». Как сказать это компьютеру, не печатая 100 строк?", hyp: "повторить N раз; цикл", goal: "Как работает цикл «повторить N раз» и цикл «пока»?", f: ["Цикл — повторение набора команд; бывает с заданным числом повторений и с условием.", "Цикл с условием («пока») выполняется, пока условие истинно; может не выполниться ни разу.", "Тело цикла — команды, которые повторяются."], t: ["цикл", "тело цикла", "условие цикла"], a: "brow", l: "blk,lbot", fl: ["robot_2", "robot_3"], s: ["Откройте «robot_2.html»: решите задачу с помощью «повторить 5 раз».", "Объясните, что изменится, если число повторов 4 или 6."], hw: "Найдите в жизни три повторяющихся процесса и опишите циклом." });
  E("циклы для управления исполнителем", [8], { m: "pc", q: "Робот должен дойти до стены, а длина коридора неизвестна. Как записать программу, подходящую для любого коридора?", hyp: "цикл «пока справа свободно»", goal: "Как применять циклы с заданным числом повторений и с условием?", f: ["Цикл «повторить N раз» используют, когда число повторений известно.", "Цикл «пока» — когда известно условие окончания.", "Типичные ошибки: бесконечный цикл, лишнее действие после цикла."], t: ["цикл «пока»", "бесконечный цикл"], a: "kumir,brow", l: "kum", fl: ["robot_3", "robot_4"], s: ["Откройте «robot_3.html» (Рамка): закрасьте периметр квадрата с помощью циклов (не более 8 строк).", "Откройте «robot_4.html» (До стены): закрасьте коридор неизвестной длины циклом «пока».", "Проверьте программу, изменив длину коридора (у учителя есть вариант с другой длиной).", "Запишите, чем отличаются циклы с заданным числом повторений и с условием."], adv: ["Решите «Рамку» программой из 5 строк."], done: "Решены две задачи с циклами.", chk: ["Следите за бесконечным циклом: страница останавливает программу через 3000 команд."], hw: "Придумайте алгоритм «Забор» (закрасить периметр поля)." });
  E("алгоритмическая конструкция .ветвление", [8], { m: "unp", q: "Если на улице дождь — берём зонт, иначе — солнечные очки. Как записать такой выбор для компьютера?", hyp: "если … то … иначе", goal: "Как работает ветвление?", f: ["Ветвление — выбор одной из двух (или нескольких) последовательностей команд по условию.", "Полная форма: «если … то … иначе …»; неполная: «если … то …».", "Условие — высказывание, значение которого ИСТИНА или ЛОЖЬ."], t: ["ветвление", "условие", "полное ветвление"], a: "brow", fl: ["robot_5"], s: ["Откройте «robot_5.html» (Только чистые): изучите команду «если клетка чистая».", "Опишите словами, как работает программа на примере коридора."], hw: "Придумайте три ситуации с ветвлением и запишите «если … иначе»." });
  E("ветвления и циклы с условием", [8], { m: "pc", q: "Робот идёт по коридору, где часть клеток уже закрашена. Как закрасить только чистые, ничего не повредив?", hyp: "цикл с ветвлением внутри", goal: "Как сочетать циклы и ветвления в программе исполнителя?", f: ["Ветвление можно вложить в цикл и наоборот.", "Условия Робота: клетка закрашена/чистая, справа/слева/сверху/снизу свободно/стена.", "Чертёжник работает по векторам и рисует при опущенном пере."], t: ["вложенные конструкции", "вектор"], a: "kumir,brow", l: "kum", fl: ["robot_5", "chert_1", "chert_2"], s: ["Откройте «robot_5.html» (Только чистые) и решите: используйте цикл и ветвление.", "Откройте «chertezhnik_1.html» (Буква Г): нарисуйте букву Г по пунктиру.", "Откройте «chertezhnik_2.html» (Ступеньки): нарисуйте ступеньки с повтором в 5 строк.", "Для каждой задачи запишите число команд и проверьте, нельзя ли короче."], adv: ["Откройте «chertezhnik_3.html» (Зубцы) и «chertezhnik_4.html» (Домик)."], done: "Решены задачи Робота и Чертёжника.", hw: "Запишите алгоритм для Чертёжника: нарисовать букву «П»." });
  E("ручное. исполнение алгоритмов", [8], { m: "pc", q: "Программа не работает, а ошибки вы не видите. Как «поиграть за компьютер» и найти место, где всё пошло не так?", hyp: "по шагам, записывая значения переменных", goal: "Как исполнять алгоритм вручную с помощью трассировочной таблицы?", f: ["Трассировка — пошаговое выполнение алгоритма с записью значений переменных.", "Трассировочная таблица: строки — шаги, столбцы — переменные и вывод.", "Метод помогает находить ошибки и определять, что делает алгоритм."], t: ["трассировка", "переменная", "шаг алгоритма"], a: "tab", fam: "trace", s: ["Для каждой задачи с листа составьте трассировочную таблицу (тетрадь или электронная таблица).", "Проверьте результат выполнением программы в Thonny (кнопка «Шаг» показывает значения переменных).", "Запишите, что делает каждый алгоритм (одним предложением)."], done: "Составлены трассировочные таблицы для 3 алгоритмов.", hw: "Составьте трассировку для программы из задания по листу." });
  E("контрольная работа по теме .исполнители", [8], { m: "unp", ctrl: true, fam: "trace", q: "Как проверить умение составлять алгоритмы?", hyp: "", goal: "Проверка по теме «Исполнители и алгоритмы».", f: [] });
  E("язык программирования python", [8], { m: "pc", q: "Мы научились писать алгоритмы словами. Как объяснить их компьютеру, чтобы он выполнил за секунду то, что человек делал бы час?", hyp: "записать на языке, который он понимает", goal: "Какие бывают данные и как хранить их в переменных на языке Python?", f: ["Переменная — именованная область памяти для данных; значение присваивают знаком =.", "Типы данных: целые (int), вещественные (float), строки (str), логические (bool).", "Функции print() и input() выводят и вводят данные; input() возвращает строку."], t: ["переменная", "тип данных", "присваивание", "строка"], a: "py", l: "thon,hpy,trin", fl: ["py_linear"], s: ["Откройте Thonny. В нижнем окне «Оболочка» введите по очереди: 2+3, 7/2, 7//2, 7%2, 2**10. Запишите результаты.", "Введите: a = 5, затем b = a*2, затем print(a, b). Что вывелось?", "Проверьте типы: type(5), type(5.0), type('5'), type(True).", "Введите: print('Привет,', input()). Нажмите Enter и введите своё имя.", "Откройте «zadacha_1.py» (Приветствие) и решите, запустите кнопкой «Запуск»."], done: "Выполнены опыты с типами данных; решена задача «Приветствие».", chk: ["Если Thonny не установлен — используйте онлайн-интерпретатор по ссылке из карточки учителя.", "Ученики часто забывают, что input() возвращает строку: нужно int(input())."], hw: "Запишите значения выражений 17//5, 17%5, 2**3 и проверьте в Python." });
  E("линейные программы", [8], { m: "pc", q: "Магазин: цена, количество, деньги. Как автоматически посчитать сдачу, если цены каждый день меняются?", hyp: "ввод данных, вычисление, вывод результата", goal: "Как писать линейные программы с вводом и выводом данных?", f: ["Линейная программа: ввод → вычисление → вывод, команды выполняются подряд.", "Ввод чисел: int(input()) для целых, float(input()) для вещественных.", "Деление: / даёт вещественное число, // — целую часть, % — остаток."], t: ["ввод", "вывод", "вычисление"], a: "py", l: "thon", py: "linear", s: [], done: "Решено не менее 4 задач из набора; проверка «proverka.py» показывает успешное выполнение.", hw: "Составьте и напишите программу «Периметр и площадь прямоугольника»." });
  E("арифметические и логические выражения", [8], { m: "pc", q: "Как компьютер решает, что 7 % 2 == 1 — правда, а число чётное?", hyp: "вычисляет значение логического выражения", goal: "Как записывать арифметические и логические выражения в программе?", f: ["Операции: +, −, *, /, //, %, **; порядок как в математике.", "Сравнения: ==, !=, <, >, <=, >= дают логическое значение.", "Логические операции: and, or, not."], t: ["выражение", "логическое выражение", "остаток"], a: "py", l: "thon", py: "linear", s: ["В оболочке Thonny вычислите: 10 % 3, 10 // 3, 5 > 3 and 2 > 4, not (5 > 3), 7 % 2 == 1.", "Решите задачи 5 и 6 из набора «linear»: «Сумма цифр двузначного числа» и «Чётное ли число?»."], hw: "Запишите логическое выражение «число n — трёхзначное»." });
  E("оператор ветвления", [8], { m: "mix", q: "Одна и та же программа должна по-разному реагировать на данные: для 85 баллов — «5», для 40 — «2». Как это записать?", hyp: "if … else", goal: "Как записывается ветвление в Python?", f: ["Условный оператор: if условие: … else: … (отступ — часть синтаксиса).", "Несколько условий: elif.", "Условие — логическое выражение."], t: ["оператор if", "отступ", "elif"], a: "py", l: "thon", py: "cond", s: ["Откройте «zadacha_1.py» (Большее из двух) и решите, запустите.", "Проверьте работу на разных данных (оба числа равны!)."], hw: "Напишите условие для определения чётного числа." });
  E("программы с ветвлением", [8], { m: "pc", q: "Как программа определит, что три отрезка образуют треугольник?", hyp: "проверка неравенства для каждой пары", goal: "Как писать программы с ветвлением?", f: ["Вложенные условия и цепочки elif позволяют выбирать из нескольких вариантов.", "Полнота проверки: рассмотрены все случаи.", "Тестирование: границы значений."], t: ["вложенное ветвление"], a: "py", l: "thon", py: "cond", s: [], done: "Решено не менее 4 задач; все тесты в «proverka.py» пройдены.", hw: "Составьте программу определения времени года по номеру месяца." });
