  E("мини-проект .угадай число", [8], { m: "pc", q: "Как сделать игру, в которой компьютер загадывает число, а вы угадываете?", hyp: "случайное число, цикл, сравнение", goal: "Как создать небольшую игровую программу с циклом и ветвлением?", f: ["Модуль random: random.randint(a, b) даёт случайное целое число.", "Цикл while работает, пока не угадано; в теле — ввод и сравнение.", "Счётчик попыток — переменная."], t: ["случайное число", "модуль", "попытка"], a: "py", l: "thon", fl: [], s: ["Создайте файл «ugaday.py». В начале: import random; secret = random.randint(1, 100); tries = 0.", "Напишите цикл while True: ввод числа, увеличение tries, сравнение: «меньше», «больше», «угадал».", "После угадывания выведите число попыток и выйдите из цикла командой break.", "Проверьте игру несколько раз; добавьте ограничение попыток (например, 7).", "Попросите соседа сыграть и дать отзыв."], adv: ["Добавьте уровни сложности (диапазон 1–10, 1–100, 1–1000).", "Поменяйтесь ролями: загадывайте вы, а программа угадывает (бинарный поиск)."], done: "Работающая игра «Угадай число» с подсчётом попыток.", chk: ["Автопроверки нет: игру проверяют вручную, сыграв раза три."], hw: "Улучшите игру: добавьте подсказки «горячо/холодно»." });
  E("анализ алгоритмов", [8], { m: "unp", q: "Две программы дают одинаковый ответ. Как понять, какая лучше и что делает незнакомая программа?", hyp: "проследить по шагам; сравнить число шагов", goal: "Как определить, что делает алгоритм, по его записи?", f: ["Анализ — определение результата алгоритма для данных.", "Алгоритмы можно сравнивать по числу шагов и понятности.", "Одинаковый результат — не значит одинаковый алгоритм."], t: ["анализ алгоритма", "результат"], a: "py", fam: "trace", s: ["Разберите три программы из листа: что они выводят для заданных входных данных?", "Проверьте себя запуском в Thonny."], hw: "Сравните два способа найти сумму чисел от 1 до n." });
  E("тестирование и отладка", [8], { m: "pc", q: "Программа запускается и даже выдаёт ответ, но ответ неверный. Как найти ошибку?", hyp: "тесты, пошаговое выполнение, вывод промежуточных значений", goal: "Как тестировать и отлаживать программы?", f: ["Тест — набор исходных данных с известным ответом.", "Ошибки: синтаксические, ошибки выполнения, логические (неверный результат).", "Отладка: пошаговое выполнение, контрольный вывод, проверка границ."], t: ["тест", "отладка", "ошибка"], a: "py", l: "thon", fl: ["bugs"], s: ["Откройте «oshibki.py»: пять небольших программ (в комментариях).", "Для каждой скопируйте код в Thonny, запустите и найдите ошибку.", "Запишите в тетради: что за ошибка и как исправили.", "Составьте для каждой программы два теста (вход → ожидаемый ответ)."], done: "Найдены и исправлены ошибки в пяти программах.", chk: ["Ключ — в файле «klyuch_oshibki.txt» (папка для учителя)."], hw: "Придумайте программу с ошибкой и обменяйтесь с соседом." });
