  E("глобальная сеть интернет", [9], { m: "pc", q: "Вы открываете сайт в другой стране за долю секунды. Через сколько «станций» проходит запрос и кто ими управляет?", hyp: "через множество маршрутизаторов и серверов; нет единого владельца", goal: "Как устроен Интернет и как данные находят дорогу?", f: ["Интернет — множество сетей, объединённых протоколами TCP/IP; данные передаются пакетами.", "Маршрутизаторы выбирают путь пакетов; DNS переводит доменные имена в IP-адреса.", "Службы: Всемирная паутина (WWW), электронная почта, передача файлов, мессенджеры."], t: ["протокол TCP/IP", "маршрутизатор", "DNS", "пакет", "домен"], a: "cmd,brow", l: "fil,res", fl: ["ip"], s: ["Откройте командную строку. Выполните «ping ya.ru» (или адрес, указанный учителем) и запишите время ответа.", "Выполните «tracert ya.ru» (Linux: «traceroute ya.ru») и посчитайте число «прыжков» до цели.", "Выполните «nslookup ya.ru» и найдите IP-адрес сайта.", "Откройте «zadanie_ip.csv» в электронной таблице: для каждого адреса определите по маске адрес сети (учебная задача, ключ у учителя).", "Объясните: что такое DNS и зачем он нужен."], done: "Записаны результаты ping, tracert, nslookup; выполнены 3 задачи на адреса.", chk: ["На некоторых школьных сетях tracert блокируется: тогда используйте только ping и nslookup."], hw: "Определите IP-адрес своего домашнего роутера (интерфейс сети) и запишите." });
  E("безопасное поведение в сети", [9], { m: "mix", q: "Вам пришло «письмо из банка» со ссылкой «срочно подтвердить данные». Как отличить настоящее от поддельного и что такое двухфакторная защита?", hyp: "проверить адрес отправителя и ссылки; не вводить данные по ссылке; включить второй фактор", goal: "Как защитить свои данные и аккаунты в сети?", f: ["Фишинг — поддельные сайты и письма для кражи данных; признаки: срочность, ошибки, странные адреса.", "Надёжный пароль: длинный, уникальный, без личных данных; удобно использовать менеджер паролей.", "Двухфакторная аутентификация требует второй подтверждающий шаг (код из СМС или приложения) — ею защищены сервисы Госуслуг."], t: ["аутентификация", "фишинг", "двухфакторная защита", "приватность"], a: "brow", l: "setev,gos", fl: ["pass", "cards_po"], s: ["Откройте «proverka_parolya.html»: проверьте образцы паролей (придуманные!) и составьте правило надёжного пароля.", "Разберите 5 учебных ситуаций (карточки учителя): письмо, сайт, звонок, флешка, просьба друга. Для каждой определите угрозу и правильные действия.", "Составьте памятку «Как защитить аккаунт»: пароль, второй фактор, подозрительные ссылки, настройки приватности.", "Прочитайте на сайте госуслуг раздел о безопасности (без входа) и выпишите три совета."], done: "Составлена памятка по безопасности из 6–7 пунктов.", chk: ["Не вводить в тренажёры настоящие пароли.", "Не открывать личные аккаунты Госуслуг на уроке."], hw: "Вместе с родителями проверьте, у каких сервисов включена двухфакторная защита." });
  E("создание веб-страницы по шаблону", [9], { m: "pc", q: "Как сделать свою страницу в Интернете без сложного программирования, используя готовый шаблон?", hyp: "заменить текст и картинки в шаблоне", goal: "Как создать веб-страницу из текста, ссылок и изображений по шаблону?", f: ["Веб-страница — файл на языке разметки HTML, отображаемый браузером.", "Теги задают структуру: заголовки, абзацы, списки, ссылки, изображения.", "Оформление хранится отдельно в таблице стилей CSS."], t: ["HTML", "тег", "гиперссылка", "CSS"], a: "web,brow", l: "mdn", fl: ["site"], s: ["Откройте папку «sayt» и файл «index.html» в Блокноте (или редакторе кода), а затем в браузере (двойной щелчок).", "Выполните задания 1–4, указанные в комментариях: замените заголовок на своё имя, напишите о себе, добавьте список из трёх интересов, вставьте картинку «foto.bmp» и ссылку.", "После каждого изменения сохраняйте файл (Ctrl+S) и обновляйте страницу в браузере (F5).", "Откройте «style.css» и измените цвет заголовка и шрифт; добавьте правило для абзацев.", "Проверьте страницу на соседнем компьютере (скопируйте папку «sayt»)."], adv: ["Создайте вторую страницу и свяжите страницы ссылками."], done: "Готова страница-визитка с заголовком, текстом, списком, картинкой и ссылкой.", chk: ["Файл сохранять в UTF-8 (Блокнот: Файл → Сохранить как → Кодировка UTF-8)."], hw: "Продолжите страницу: добавьте раздел «Мои проекты»." });
  E("^поиск информации в интернете$", [9], { m: "mix", q: "Почему два человека, вводя один и тот же запрос, иногда получают разные результаты?", hyp: "учитывается местоположение, история, реклама", goal: "Как работают поисковые системы и логические операции в запросах?", f: ["Поисковый робот обходит страницы и составляет индекс; ответ формируется по релевантности.", "Запрос можно уточнить операциями: пробел — И, | — ИЛИ, минус — НЕ, кавычки — точная фраза.", "Результаты зависят от региона, языка и настроек пользователя."], t: ["поисковый индекс", "релевантность", "логический запрос"], a: "brow", l: "yah", fl: ["truth"], s: ["Откройте справку Яндекса (или справку другой поисковой системы) и выпишите операторы запроса.", "Свяжите операции запроса с логическими операциями И, ИЛИ, НЕ: заполните таблицу соответствия."], hw: "Придумайте 3 запроса с операциями и объясните." });
  E("поисковые запросы с логическими операциями", [9], { m: "pc", q: "Найдите стихотворение, в котором есть слово «звезда», но нет слова «ночь». Как сформулировать запрос?", hyp: "звезда -ночь", goal: "Как составлять поисковые запросы с логическими операциями?", f: ["Пробел между словами означает И (в большинстве систем).", "Оператор | — ИЛИ; знак минус перед словом — исключение; кавычки — точная фраза.", "Дополнительные операторы: site: (искать на сайте), mime: (тип файла)."], t: ["логические операции", "оператор запроса"], a: "brow", l: "yah", fl: ["truth"], s: ["Заполните таблицу: цель поиска — запрос — число найденных результатов — подходят ли первые 3 результата.", "Выполните задачи: 1) страницы о кошках и собаках; 2) страницы о кошках, но не о собаках; 3) точная фраза «информационные технологии»; 4) документы PDF на сайте school.ru-подобных сайтов (используйте site: и mime:).", "Сравните количество результатов в запросах с И и ИЛИ — объясните закономерность.", "Сделайте вывод: какие операции уточняют, а какие расширяют поиск."], done: "Заполнена таблица запросов, сделан вывод о влиянии операций.", chk: ["Операторы разных поисковых систем различаются — сверяйтесь со справкой."], hw: "Составьте запрос для поиска информации к докладу по другому предмету." });
  E("онлайн-офис", [9], { m: "pc", q: "Как вчетвером работать над одним документом одновременно, если вы находитесь в разных домах? И как не поверить недостоверной информации?", hyp: "общий онлайн-документ; проверять источники", goal: "Как работать в онлайн-офисе и оценивать достоверность информации?", f: ["Онлайн-офис позволяет создавать документы в браузере и работать над ними совместно.", "Права доступа: просмотр, комментирование, редактирование.", "Достоверность проверяют по нескольким независимым источникам, дате публикации, авторству."], t: ["совместная работа", "права доступа", "достоверность"], a: "txt,brow", l: "only,r7,myo", fl: ["docdraft"], s: ["Объединитесь в группы по 3–4 человека; один создаёт документ в онлайн-офисе школы (или в локальной программе, если онлайн недоступен) и даёт доступ остальным.", "Каждый пишет свой раздел (описание темы урока) в общем документе, используя режим «Рецензирование/Комментарии».", "Найдите один сомнительный факт и проверьте его в двух источниках; оставьте комментарий со ссылкой.", "Оформите итоговый документ: заголовки, список источников.", "Скачайте копию в формате docx и сохраните в личную папку."], done: "Создан совместный документ с разделами, комментариями и источниками.", chk: ["Используйте только учебные аккаунты школы или локальный офис.", "Если доступа к онлайн-сервису нет — выполните задание по очереди в одном локальном файле, используя «Рецензирование»."], hw: "Напишите правила проверки информации из двух пунктов." });
  E("моделирование как метод познания", [9], { m: "unp", q: "Чтобы испытать новый самолёт, не обязательно строить настоящий. Как «проверить» то, чего ещё нет или что опасно испытывать?", hyp: "построить модель", goal: "Что такое модель и как проходит моделирование?", f: ["Модель — упрощённый образ объекта или процесса, отражающий нужные свойства.", "Этапы моделирования: постановка задачи, построение модели, эксперимент, анализ результатов.", "Виды моделей: натурные, информационные (таблицы, схемы, формулы), компьютерные."], t: ["модель", "моделирование", "адекватность"], a: "brow", l: "phet", fl: [], s: ["Составьте таблицу «Объект — для чего модель — вид модели» для 5 примеров."], hw: "Приведите пример модели из школьной физики или биологии." });
  E("графы и деревья как модели", [9], { m: "mix", q: "Как показать схему метро, родословное дерево и структуру папок одним способом?", hyp: "точки и линии: граф", goal: "Что такое граф и дерево и как их использовать как модели?", f: ["Граф состоит из вершин и рёбер; бывает ориентированным и взвешенным.", "Дерево — связный граф без циклов; в нём есть корень и листья.", "Путь, цикл, степень вершины — основные понятия."], t: ["граф", "вершина", "ребро", "дерево"], a: "gv", l: "gvo,dio", fl: [], s: ["Постройте в draw.io (или Graphviz Online) граф «карта» из 6 вершин: города и дороги (вымышленные). Определите степень каждой вершины.", "Постройте дерево папок школьного компьютера (5–7 вершин).", "Запишите граф матрицей смежности в электронной таблице."], done: "Построены граф и дерево, записана матрица смежности.", hw: "Составьте родословное дерево (3 поколения) и определите число листьев." });
  E("создание однотабличной базы данных", [9], { m: "pc", q: "Школьная библиотека хранит 5 000 книг. Как быстро найти все книги про войну, изданные до 1950 года?", hyp: "в базе данных с полями и запросами", goal: "Как создать однотабличную базу данных?", f: ["База данных — организованная совокупность данных; таблица состоит из записей (строк) и полей (столбцов).", "У каждого поля есть имя и тип (текст, число, дата).", "Ключ — поле, значения которого однозначно определяют запись."], t: ["база данных", "запись", "поле", "тип данных", "ключ"], a: "db,tab", l: "sqb", fl: ["db"], s: ["Откройте DB Browser for SQLite: «Файл → Новая база данных», сохраните как «Фамилия_biblioteka.db».", "Создайте таблицу «knigi» с полями: id (целое, ключ), nazvanie (текст), avtor (текст), god (целое), zhanr (текст), ekz (целое).", "Импортируйте данные из «baza/knigi.csv» (Файл → Импорт → Таблицу из файла CSV) либо введите 6 записей вручную.", "Просмотрите данные на вкладке «Данные». Добавьте две записи о книгах, которые читали сами.", "Если программа DB Browser недоступна: откройте «knigi.csv» в электронных таблицах, оформите как список с заголовками и закрепите первую строку."], done: "Создана база с таблицей «knigi» и не менее 18 записями.", chk: ["Файлы CSV используют разделитель «;», в импорте нужно выбрать его."], hw: "Придумайте поля для базы «Моя коллекция»." });
  E("поиск данных в готовой базе", [9], { m: "pc", q: "Как найти всё нужное в базе, не просматривая её построчно?", hyp: "сортировка, фильтр, запрос", goal: "Как искать данные сортировкой, фильтрацией и запросом?", f: ["Сортировка упорядочивает записи по значениям поля.", "Фильтр оставляет записи, удовлетворяющие условию; условия можно объединять И/ИЛИ.", "Запрос на выборку: SELECT поля FROM таблица WHERE условие."], t: ["фильтр", "сортировка", "запрос"], a: "db,tab", l: "sqb,sqo", fl: ["db"], s: ["Откройте базу «Фамилия_biblioteka.db» (из прошлого урока) или файл «biblioteka.sql» через «Файл → Импорт → База из SQL».", "Выполните отбор: книги, изданные до 1850 года (фильтр по столбцу «Год»).", "Отсортируйте по году издания по убыванию.", "Во вкладке «Выполнить SQL» введите: SELECT nazvanie, god FROM knigi WHERE god < 1850; сравните с фильтром.", "Найдите все повести (жанр = «повесть») и все книги, у которых больше 4 экземпляров.", "Запишите три найденные книги и условие отбора."], done: "Выполнены 4 вида поиска: фильтр, сортировка, SQL, составное условие.", hw: "Составьте 3 вопроса к базе «Библиотека» и запишите условия отбора." });
  E("готовыми компьютерными моделями", [9], { m: "pc", q: "Как изучить движение, рост популяции или электрическую цепь, не имея лаборатории?", hyp: "компьютерная модель с настройками", goal: "Как изучать объекты с помощью готовых компьютерных моделей?", f: ["Компьютерная модель позволяет менять параметры и наблюдать результат.", "Эксперимент ведут по плану: гипотеза, изменение одного параметра, запись результатов.", "Результаты модели нужно проверить на правдоподобие."], t: ["параметр", "эксперимент", "гипотеза"], a: "sim,tab", l: "phet", fl: ["sheet_model"], s: ["Откройте модель на PhET (например, «Движение снаряда» или «Баланс химических уравнений», если разрешено) либо скачанную версию.", "Сформулируйте гипотезу: как изменится результат, если увеличить параметр?", "Проведите по 5 экспериментов с изменением одного параметра и запишите в таблицу.", "Постройте график зависимости в электронной таблице.", "Сделайте вывод и оцените, насколько модель правдоподобна."], done: "Проведён эксперимент с моделью, построен график, сделан вывод.", chk: ["Если PhET недоступен, используйте модели из цифровых пособий класса."], hw: "Выберите модель по другому предмету и опишите её параметры." });
  E("математические модели", [9], { m: "unp", q: "Вклад в банке растёт «сам»: как заранее узнать, сколько денег будет через 5 лет?", hyp: "по формуле", goal: "Как строить математические модели и реализовывать их в программе?", f: ["Математическая модель — формулы, уравнения, неравенства.", "Для реализации модели записывают алгоритм вычислений по шагам.", "Результат анализируют: сравнивают с ожидаемым."], t: ["математическая модель", "параметры", "алгоритм вычисления"], a: "py", fl: [], s: ["Составьте формулу вклада с процентами; рассчитайте вручную 3 года.", "Опишите алгоритм вычислений по шагам."], hw: "Выведите формулу для вклада без накопления процентов." });
  E("программная реализация простейшей", [9], { m: "pc", q: "Можно ли заставить компьютер «прожить» 10 лет вклада за секунду и показать результат?", hyp: "да: цикл по годам", goal: "Как реализовать простейшую модель в программе?", f: ["Модель задают параметрами и правилами изменения на шаге.", "Цикл повторяет шаг нужное число раз; результат выводится.", "Меняя параметры, исследуют модель."], t: ["шаг моделирования", "параметр модели"], a: "py", l: "thon", py: "model", s: [], done: "Решены три задачи на моделирование.", hw: "Измените модель: добавьте ежегодное пополнение вклада." });
