  E("^системы счисления\\. перевод", [10], { m: "mix", q: "Почему для адресов и цветов программисты используют шестнадцатеричную запись, а не десятичную?", hyp: "компактна и легко связана с двоичной", goal: "Как переводить числа между системами счисления?", f: ["Перевод из p-ичной в десятичную: сумма цифр, умноженных на степени основания.", "Перевод из десятичной в p-ичную: деление на p с остатками (целая часть).", "Двоичная, восьмеричная и шестнадцатеричная связаны группировкой разрядов (по 3 и 4)."], t: ["основание", "разряд", "тетрада"], a: "brow,py", fl: ["binary", "py_base"], fam: "ns", s: ["Решите задачи на перевод (лист).", "Напишите программу перевода числа в k-ичную систему (задача «Число в системе с основанием k» из набора) и сверьте с ручным расчётом."], hw: "Переведите три числа в 5-ичную систему." });
  E("арифметика в позиционных", [10], { m: "unp", q: "Как компьютер вычитает, если у него нет отрицательных чисел? И почему 1 + 1 = 10?", hyp: "по правилам двоичной арифметики", goal: "Как выполнять арифметические операции в разных системах счисления?", f: ["Сложение и умножение выполняют по таблицам в данной системе с переносом в следующий разряд.", "Вычитание — с заёмом либо через дополнительный код.", "Проверка — переводом в десятичную."], t: ["перенос", "заём"], a: "brow", fam: "nsadd", s: ["Выполните сложение, вычитание и умножение в двоичной и 8-ричной системах (лист)."], hw: "Сложите числа в 16-ричной системе: A7 + 3F." });
  E("представление чисел", [10], { m: "pc", q: "Почему в программе 0.1 + 0.2 не равно 0.3 и как компьютер хранит отрицательные числа?", hyp: "числа хранятся в двоичном виде с ограничениями", goal: "Как числа хранятся в памяти компьютера?", f: ["Целые числа без знака занимают n бит и принимают значения 0…2ⁿ−1.", "Целые со знаком хранят в дополнительном коде: диапазон −2ⁿ⁻¹ … 2ⁿ⁻¹−1.", "Вещественные числа хранят в формате с плавающей запятой (знак, порядок, мантисса); возможна потеря точности."], t: ["дополнительный код", "разрядность", "формат с плавающей запятой"], a: "brow,py", fl: ["number"], s: ["Откройте «chislo_v_pamyati.html»: введите 5, −5, 127, −128, 128 и запишите коды в 8 битах.", "Объясните, почему число 128 не помещается в 8 бит со знаком.", "Для вещественных чисел введите 0.5, 0.1, 0.25 и запишите порядок и мантиссу.", "В Python выполните: 0.1 + 0.2 == 0.3 и 0.5 + 0.25 == 0.75. Объясните разницу."], done: "Записаны коды чисел, объяснены ограничения разрядности и точности.", hw: "Найдите наибольшее и наименьшее 16-битное число со знаком." });
  E("кодирование текста\\. ascii", [10], { m: "pc", q: "Почему в одном мессенджере эмодзи 😀 видно, а в старой программе — «???» и в чём разница между ASCII, Windows-1251 и UTF-8?", hyp: "разные таблицы кодов и их объём", goal: "Как работают кодировки ASCII, Юникод и UTF-8?", f: ["ASCII — 7-битная таблица (128 символов: латиница, цифры, знаки).", "Юникод присваивает каждому символу номер (кодовую позицию); UTF-8, UTF-16 — способы записи этих номеров байтами.", "В UTF-8 латиница занимает 1 байт, кириллица — 2 байта, эмодзи — до 4 байт."], t: ["Юникод", "UTF-8", "кодовая позиция"], a: "note,brow", fl: ["codes"], s: ["Откройте «tablica_kodov.html» и введите «Hello», «Привет», «Ёжик 😀». Для каждого символа запишите Unicode и UTF-8 байты.", "Откройте файлы из «kodirovki» в Блокноте с разными кодировками; определите правильную для каждого.", "Определите размер каждого файла и объясните разницу.", "Решите задачи на размер текста в разных кодировках (лист)."], done: "Определены кодировки файлов, рассчитаны размеры.", hw: "Закодируйте слово «Информатика» последовательностью кодов UTF-8 (hex)." });
  E("^кодирование графической", [10], { m: "mix", q: "Фото 12 мегапикселей занимает на карте всего 4 МБ, хотя в несжатом виде должно быть 36 МБ. Куда делась разница?", hyp: "сжатие", goal: "Как кодируется графика и от чего зависит размер файла?", f: ["Растровая графика: размер = ширина × высота × глубина цвета (бит).", "Цветовые модели: RGB (экран), CMYK (печать), индексированные палитры.", "Векторная графика хранит описания фигур, не зависит от разрешения."], t: ["разрешение", "глубина цвета", "палитра"], a: "tab", fam: "vol", s: ["Рассчитайте размеры изображений при разных параметрах (лист) в электронной таблице."], hw: "Сколько памяти нужно для экрана 1920×1080 при 24 битах на пиксель?" });
  E("дискретизация графической информации", [10], { m: "pc", q: "Как превратить изображение в числа и насколько можно уменьшить разрешение, не потеряв смысл?", hyp: "уменьшать до тех пор, пока узнаём картинку", goal: "Как дискретизация и глубина цвета влияют на качество и размер изображения?", f: ["Дискретизация изображения — разбиение на пиксели; число пикселей определяет разрешение.", "Квантование — округление цвета до ограниченного числа значений (глубина цвета).", "Меньше пикселей и цветов — меньше размер, но ниже качество."], t: ["дискретизация", "квантование", "разрешение"], a: "rast,tab", fl: ["photo", "raster"], s: ["Откройте «foto_zadanie.bmp» (320×240) в растровом редакторе и запишите размер файла.", "Измените размер до 160×120, 80×60, 40×30; сохраняйте копии как PNG и BMP.", "Запишите размер каждого файла и разрешение.", "Уменьшите глубину цвета (индексированная палитра 256 цветов, 16 цветов, 2 цвета), сравните качество и размер.", "Заполните таблицу и сделайте вывод: оптимальный компромисс для публикации на сайте."], done: "Построена таблица зависимости размера и качества от разрешения и глубины цвета.", hw: "Выберите оптимальные параметры для фото на странице школьного сайта." });
  E("кодирование звуковой", [10], { m: "mix", q: "Почему телефонный разговор звучит «плоско», а запись на студии — «живая»? Только ли в микрофоне дело?", hyp: "в частоте и глубине записи", goal: "Как кодируется звук и как рассчитывать объём записи?", f: ["Объём звука V = f · i · t · k (частота, глубина, время, число каналов).", "Телефон — около 8 кГц; музыка CD — 44,1 кГц, 16 бит, стерео.", "Теорема Котельникова: частота дискретизации должна не менее чем вдвое превышать наибольшую частоту сигнала."], t: ["частота дискретизации", "глубина кодирования", "квантование"], a: "tab,brow", fl: ["sound"], fam: "vol", s: ["Решите расчётные задачи на объём звука (лист).", "Откройте «diskretizaciya_zvuka.html» и объясните, как меняется «ступенчатая» линия."], hw: "Рассчитайте объём трёхминутной песни в CD-качестве." });
  E("дискретизация звуковой информации", [10], { m: "pc", q: "Какой минимальный набор параметров нужен, чтобы человеческий голос в записи был разборчивым и файл не был огромным?", hyp: "8–16 кГц и 8–16 бит", goal: "Как параметры записи влияют на качество и размер звука?", f: ["Чем выше частота и глубина, тем точнее звук и больше файл.", "Для речи достаточно 8–16 кГц, для музыки — 44,1 кГц и выше.", "Сжатие (MP3, OGG) уменьшает размер за счёт потерь."], t: ["формат звука", "сжатие с потерями"], a: "aud", l: "auda", fl: ["sound"], s: ["В Audacity запишите фразу 10 секунд (или откройте «zvuk_ton_440.wav»).", "Экспортируйте её как WAV с частотой 8000, 22050, 44100 Гц и глубиной 8 и 16 бит.", "Сравните размеры файлов с расчётом из таблицы «tablica_zvuka.csv».", "Сохраните в MP3 или OGG и сравните размер и качество на слух.", "Сделайте вывод: какие параметры выбрать для голоса и для музыки."], done: "Сделаны записи с разными параметрами, размеры сопоставлены с расчётом.", chk: ["Если микрофоны недоступны, меняйте частоту проекта в Audacity на готовом файле."], hw: "Рассчитайте размер минутной записи голоса при 16 кГц, 16 бит, моно." });
  E("высказывания и логические операции", [10], { m: "unp", q: "Как записать условие «поступает в профильный класс, если балл не ниже 70 и есть олимпиада или экзамен сдан на отлично»?", hyp: "логическое выражение", goal: "Какие логические операции есть и как записать сложное условие?", f: ["Операции: ¬ (НЕ), ∧ (И), ∨ (ИЛИ), → (импликация), ≡ (эквивалентность), ⊕ (исключающее ИЛИ).", "Приоритет: ¬, затем ∧, затем ∨, затем →, затем ≡.", "Импликация A → B ложна только при A = 1 и B = 0."], t: ["конъюнкция", "дизъюнкция", "импликация", "эквивалентность"], a: "brow", fl: ["truth", "gates"], fam: "logic", s: ["Откройте «tablica_istinnosti.html» и постройте таблицы для imp(A,B), eq(A,B), xor(A,B).", "Запишите условие «поступления» в виде логического выражения."], hw: "Запишите логическим выражением условие «число двузначное и чётное»." });
  E("таблицы истинности\\. законы", [10], { m: "pc", q: "Как узнать, что два разных на вид выражения означают одно и то же?", hyp: "построить таблицы и сравнить", goal: "Как строить таблицы истинности и пользоваться законами алгебры логики?", f: ["Законы: коммутативность, ассоциативность, дистрибутивность, идемпотентность, поглощение, законы де Моргана.", "Равносильность проверяют таблицами истинности.", "Импликация выражается так: A → B = ¬A ∨ B."], t: ["закон де Моргана", "равносильность", "поглощение"], a: "brow", fl: ["truth"], fam: "logic", s: ["В «tablica_istinnosti.html» проверьте закон де Моргана и закон поглощения A or (A and B) = A.", "Постройте таблицу для выражения с тремя переменными и подсчитайте число единиц.", "Проверьте равносильность двух выражений из листа."], done: "Проверено три равносильности, построена таблица для 3 переменных.", hw: "Докажите таблицей закон дистрибутивности." });
  E("упрощение логических", [10], { m: "unp", q: "Почему инженеры стараются упрощать логические схемы? Что даёт экономия одного элемента на миллионе микросхем?", hyp: "дешевле, быстрее, меньше энергии", goal: "Как упрощать логические выражения?", f: ["Упрощение выполняют, применяя законы алгебры логики.", "Ключевые приёмы: раскрытие импликации, законы де Моргана, поглощение, склеивание.", "Результат проверяют таблицей."], t: ["упрощение", "склеивание"], a: "brow", fl: ["truth"], fam: "logic", s: ["Упростите 4 выражения (лист), проверьте по таблице на странице."], hw: "Упростите выражение ¬(A ∨ B) ∨ A." });
  E("логические уравнения", [10], { m: "unp", q: "Сколько существует наборов значений A, B, C, при которых (A ∨ B) ∧ ¬C истинно? Можно ли узнать, не перебирая все?", hyp: "по таблице или рассуждением", goal: "Как решать логические уравнения?", f: ["Решение логического уравнения — набор значений переменных, обращающий его в истину.", "Методы: таблица истинности, упрощение, рассуждения по структуре выражения.", "Число решений зависит от числа переменных (2ⁿ наборов)."], t: ["логическое уравнение", "решение"], a: "brow", fl: ["truth"], fam: "leq", s: ["Найдите число решений для 4 уравнений (лист) двумя способами: рассуждением и проверкой на «tablica_istinnosti.html»."], hw: "Решите уравнение (A → B) ∧ (B → C) = 1: сколько решений?" });
  E("нормальные формы", [10], { m: "unp", q: "Как по таблице истинности записать формулу, не угадывая?", hyp: "по строкам, где функция равна 1", goal: "Как строить ДНФ и КНФ по таблице истинности?", f: ["ДНФ (дизъюнктивная нормальная форма) — дизъюнкция конъюнкций; строят по строкам, где F = 1.", "КНФ (конъюнктивная) — конъюнкция дизъюнкций; строят по строкам, где F = 0.", "Любую логическую функцию можно записать в ДНФ или КНФ."], t: ["ДНФ", "КНФ", "минтерм"], a: "brow", fl: ["truth"], fam: "logic", s: ["По таблице из листа запишите ДНФ и КНФ.", "Проверьте полученные формулы в «tablica_istinnosti.html»."], hw: "Запишите ДНФ для функции «большинство» трёх переменных." });
  E("логические элементы компьютера", [10], { m: "mix", q: "Как из переключателей собрать устройство, которое складывает два бита?", hyp: "из логических элементов", goal: "Как работают логические элементы и сумматор?", f: ["Элементы И, ИЛИ, НЕ, исключающее ИЛИ, И-НЕ, ИЛИ-НЕ.", "Полусумматор складывает два бита: сумма = A ⊕ B, перенос = A ∧ B.", "Из полусумматоров строят сумматор."], t: ["логический элемент", "полусумматор", "триггер"], a: "brow", l: "fal", fl: ["gates"], fam: "logic", s: ["Откройте «logicheskie_elementy.html» и составьте таблицу для элементов.", "Постройте схему полусумматора из элементов (бумага или Falstad)."], hw: "Постройте схему для функции F = A ⊕ B из элементов И, ИЛИ, НЕ." });
  E("решение логических задач", [10], { m: "unp", q: "Из трёх подозреваемых лжёт только один. Как найти виновного по таблице?", hyp: "перебор вариантов с проверкой условий", goal: "Как решать логические задачи средствами алгебры логики?", f: ["Условие записывают логическими выражениями.", "Используют перебор или таблицу.", "Проверяют полученный ответ на соответствие условию."], t: ["логическая задача"], a: "brow", fam: "logic", s: ["Решите три задачи листа, записав условия логическим выражением и проверив их на странице."], hw: "Составьте и решите свою логическую задачу." });
  E("контрольная работа по теме .элементы алгебры логики", [10], { m: "unp", ctrl: true, fam: "logic", q: "Как проверить умение работать с логикой?", hyp: "", goal: "Проверка по теме «Элементы алгебры логики».", f: [] });
  E("многостраничные документы", [10], { m: "pc", q: "Реферат на 30 страниц пришлось набирать заново после добавления одной главы: все номера и оглавление «поплыли». Как этого избежать?", hyp: "использовать стили, автоматическое оглавление", goal: "Как создавать многостраничный документ со стилями и оглавлением?", f: ["Стили (Заголовок 1, 2, Основной текст) задают единое оформление.", "Оглавление собирается автоматически из заголовков.", "Разделы и разрывы страниц управляют форматированием и нумерацией."], t: ["стиль", "оглавление", "раздел", "разрыв страницы"], a: "txt", fl: ["docdraft"], s: ["Откройте «chernovik.txt» и сохраните как «Фамилия_реферат.docx».", "Примените стили: заголовки «Раздел …» — Заголовок 1; основной текст — собственный стиль «Текст» (14 pt, интервал 1,5, отступ 1,25 см).", "Добавьте титульный лист без нумерации; нумерацию страниц начните со второй страницы.", "Вставьте автоматическое оглавление после титульного листа (Ссылки → Оглавление / Writer: Вставка → Оглавление).", "Добавьте сноску и список источников.", "Сделайте экспорт в PDF и проверьте оглавление."], done: "Готов многостраничный документ с оглавлением, нумерацией и сносками.", chk: ["Проверить: заголовки оформлены стилем, а не вручную."], hw: "Оформите свой реферат по требованиям к проектным работам." });
  E("коллективная работа над документом", [10], { m: "pc", q: "Четыре человека правят один файл и присылают его друг другу по очереди — какие неприятности возможны и как их избежать?", hyp: "потеря правок, путаница версий", goal: "Как организовать коллективную работу над документом?", f: ["Режим рецензирования (исправления) показывает, кто и что изменил.", "Комментарии — для обсуждения без изменения текста.", "Совместное редактирование в облаке или сравнение/объединение версий локально."], t: ["рецензирование", "исправления", "версия"], a: "txt", l: "only", fl: ["docdraft"], s: ["В тройках откройте «chernovik.txt» и сохраните его как «Группа_документ.docx».", "Включите запись исправлений; каждый вносит правки в свой раздел, оставляя комментарии к чужим.", "Передайте документ по кругу; последний принимает или отклоняет исправления.", "Если доступно совместное редактирование — повторите в онлайн-офисе с одновременной работой.", "Сохраните итоговую версию; запишите, какие проблемы возникли и как их решали."], done: "Итоговый документ принят после рецензирования, составлен список проблем и решений.", hw: "Составьте правила коллективной работы над документом (5 пунктов)." });
